import com.sun.source.tree.*;import com.sun.source.util.*;import javax.tools.*;import java.nio.file.*;import java.util.*;
public final class ExtractWorkspace {
 public static void main(String[] args)throws Exception {
  String source=Files.readString(Path.of(args[0]));Set<String> names=new LinkedHashSet<>(List.of("REQUEST_WORKSPACE_TREE","WORKSPACE_MAIN","WORKSPACE_DELIVERY","workspaceGeneration","workspaceRegistryBusy","workspaceRootList","workspaceBrowser","WorkspaceFrame","WorkspaceLoad","WorkspaceBrowser","WorkspaceRootList","workspaceLive","cancelWorkspaceNavigation","addWorkspaceFolderActions","launchWorkspaceFolderPicker","handleWorkspaceTreeResult","showWorkspaceFolders","showWorkspaceRootOptions","removeWorkspaceRoot","workspaceRootListCurrent","openWorkspaceRoot","workspaceBrowserCurrent","loadWorkspaceFrame","acceptWorkspacePage","workspaceRowCurrent","selectWorkspaceEntry","openWorkspaceFile","workspaceUp","workspaceLocalButton","workspaceMessage","onPause","onDestroy","styleDialog","historyDialogBuilder","workspaceRootRows","workspaceTitle","workspaceDialogShown","protectionStatusRequest","protectionStatusDialog","invalidateProtectionStatus","favoriteRequest","favoriteDialog","cancelWorkspaceFavorites","favoriteCurrent","pinWorkspaceFavorite","pinCurrentDocumentFavorite","removeWorkspaceFavorite","openWorkspaceFavorite","showWorkspaceFavoriteOptions","showWorkspaceFavorites","showRemoveWorkspaceFavorite","readerRequest","readerDialog","invalidateReaderActions","readerActionCurrent","readerDialogShow","saveReaderAnchor","promptReaderBookmark","removeReaderBookmark","navigateReaderAnchor","showReaderBookmarkOptions","showReaderPlaces","showRemoveReaderBookmark"));
  JavaCompiler c=ToolProvider.getSystemJavaCompiler();JavacTask task=(JavacTask)c.getTask(null,null,null,List.of("-proc:none"),null,c.getStandardFileManager(null,null,null).getJavaFileObjects(args[0]));CompilationUnitTree unit=task.parse().iterator().next();SourcePositions p=Trees.instance(task).getSourcePositions();Map<String,String> found=new LinkedHashMap<>();String pickerRoute=null;
  for(Tree t:unit.getTypeDecls())if(t instanceof ClassTree)for(Tree m:((ClassTree)t).getMembers()){if(m instanceof MethodTree&&((MethodTree)m).getName().contentEquals("onActivityResult"))for(StatementTree statement:((MethodTree)m).getBody().getStatements())if(statement instanceof IfTree&&((IfTree)statement).getCondition().toString().contains("REQUEST_WORKSPACE_TREE"))pickerRoute=source.substring((int)p.getStartPosition(unit,statement),(int)p.getEndPosition(unit,statement));String n=m instanceof MethodTree?((MethodTree)m).getName().toString():m instanceof ClassTree?((ClassTree)m).getSimpleName().toString():m instanceof VariableTree?((VariableTree)m).getName().toString():"";if(names.contains(n))found.put(n,source.substring((int)p.getStartPosition(unit,m),(int)p.getEndPosition(unit,m)));}
  if(!found.keySet().equals(names)){names.removeAll(found.keySet());throw new AssertionError("Missing actual workspace members: "+names);}
  if(pickerRoute==null)throw new AssertionError("Missing actual tree result routing before generic document grants");
  Files.writeString(Path.of(args[2]),Files.readString(Path.of(args[1])).replace("/* MEMBERS */",String.join("\n",found.values())).replace("/* PICKER_ROUTE */",pickerRoute).replace("MainActivity.this","WorkspaceHarness.this"));
 }
}
